glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec3 col = c.rgb;
  for (int l = 0; l < 3; l++) {
    float fl = float(l);
    float sc = 9.0 + fl * 7.0;
    vec2 p = uv * vec2(sc * uRatio, sc);
    p.y += uTime * (0.8 + fl * 0.4);
    p.x += sin(uTime * 0.6 + fl + uv.y * 4.0) * 0.4;
    vec2 id = floor(p);
    vec2 f = fract(p) - 0.5;
    vec2 o = vec2(hash(id), hash(id + 3.1)) - 0.5;
    float s = smoothstep(0.09 - fl * 0.02, 0.0, length(f - o * 0.6)) * step(0.55, hash(id + 7.7));
    col = mix(col, vec3(1.0), s * uAmount);
  }
  return vec4(col, c.a);
}
